const raw = $input.first().json;

let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

const task_id     = data.task_id     || raw.task_id     || 'TASK-COST-' + Date.now();
const environment = data.environment || raw.environment || 'staging';
const service     = data.service     || raw.service     || {
  url:       'https://app-' + environment + '.monprojet.com',
  framework: 'express',
  language:  'javascript',
  status:    'HEALTHY'
};
const thresholds  = data.thresholds  || raw.thresholds  || {
  max_cost_per_hour_usd: 0.5,
  max_response_time_ms:  1000,
  max_cpu_percent:       80,
  max_memory_percent:    85
};

return [{
  json: {
    task_id:     String(task_id),
    environment: String(environment),
    service:     service,
    thresholds:  thresholds,
    simulate:    String(data.simulate || '')
  }
}];

const input = $input.first().json;
return [{
  json: {
    success: false,
    agent: "Agent Cost & Performance",
    task_id: "unknown",
    status: "ERROR",
    error_code: input.error_code,
    error_message: input.error_message,
    approved_for_pipeline: false,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;

const url = input.service_url || '';
const simulate = input.simulate || '';
const max_cost = input.max_cost_per_hour;
const max_response_time = input.max_response_time;
const max_cpu = input.max_cpu;
const max_memory = input.max_memory;
const environment = input.environment;

// Détection du scénario
const is_expensive = simulate === 'alert'
  || url.includes('heavy') || url.includes('overload');
const is_warn = simulate === 'optimize'
  || url.includes('slow') || url.includes('perf');

// Métriques simulées
const metrics = {
  response_time_ms: is_expensive ? 2500 : is_warn ? 1500 : 320,
  cpu_percent: is_expensive ? 92 : is_warn ? 65 : 35,
  memory_percent: is_expensive ? 88 : is_warn ? 75 : 52,
  requests_per_minute: is_expensive ? 12 : 85,
  cost_per_hour_usd: is_expensive ? 1.2 : is_warn ? 0.4 : environment === 'production' ? 0.35 : 0.08,
  cost_per_request_usd: is_expensive ? 0.0017 : 0.00004
};

// Violations
const violations = [];
if (metrics.cost_per_hour_usd > max_cost)
  violations.push(`Coût ${metrics.cost_per_hour_usd}$/h > seuil ${max_cost}$/h`);
if (metrics.response_time_ms > max_response_time)
  violations.push(`Response time ${metrics.response_time_ms}ms > seuil ${max_response_time}ms`);
if (metrics.cpu_percent > max_cpu)
  violations.push(`CPU ${metrics.cpu_percent}% > seuil ${max_cpu}%`);
if (metrics.memory_percent > max_memory)
  violations.push(`Mémoire ${metrics.memory_percent}% > seuil ${max_memory}%`);

// Optimisations
const optimizations = [];
if (metrics.cpu_percent > 60)
  optimizations.push('Considérer une mise à l\'échelle horizontale');
if (metrics.memory_percent > 70)
  optimizations.push('Analyser les fuites mémoire potentielles');
if (metrics.response_time_ms > 500)
  optimizations.push('Ajouter un cache Redis pour les requêtes fréquentes');
if (metrics.cost_per_hour_usd > max_cost * 0.7)
  optimizations.push('Évaluer un plan d\'hébergement plus adapté');

// Action
const action = violations.length >= 2 || metrics.cpu_percent > max_cpu
  ? 'ALERT'
  : violations.length === 1 || optimizations.length >= 2
    ? 'OPTIMIZE'
    : 'OK';

const performance_score = Math.max(0,
  100 - (violations.length * 25) - (optimizations.length * 5)
);

return [{
  json: {
    task_id: input.task_id,
    environment,
    action,
    metrics,
    violations,
    optimizations,
    performance_score,
    recommendations: action === 'ALERT'
      ? ['Intervention immédiate requise', ...violations.map(v => `Corriger : ${v}`), ...optimizations]
      : action === 'OPTIMIZE'
        ? optimizations
        : ['Performances et coûts dans les seuils — aucune action requise']
  }
}];

const input = $input.first().json;

const statusMap = { OK: 'PASS', OPTIMIZE: 'NEEDSIMPROVEMENT', ALERT: 'FAIL' };
const status = statusMap[input.action] || 'FAIL';
const scoreMap = { PASS: 100, NEEDSIMPROVEMENT: 65, FAIL: 0 };

return [{
  json: {
    agent: "Agent Cost & Performance",
    task_id: input.task_id,
    status,
    global_score: input.performance_score || scoreMap[status],
    approved_for_pipeline: status === 'PASS',
    language: "javascript",
    critical_issues: status === 'FAIL'
      ? input.violations.map(v => ({ severity: "high", description: v }))
      : [],
    warnings: status === 'NEEDSIMPROVEMENT'
      ? input.violations.map(v => ({ severity: "medium", description: v }))
      : [],
    recommendations: input.recommendations || [],
    summary: `Action : ${input.action} — ${input.violations.length} violation(s)`,
    dimensions: {
      security: { score: 100 },
      quality: { score: input.performance_score || scoreMap[status] }
    },
    action: input.action,
    metrics: input.metrics,
    timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;
const status = input.status;

return [{
  json: {
    success: status === 'PASS' ? true : status === 'NEEDSIMPROVEMENT' ? null : false,
    agent: "Agent Cost & Performance",
    task_id: input.task_id,
    status,
    global_score: input.global_score,
    approved_for_pipeline: status === 'PASS',
    action: input.action,
    critical_issues: input.critical_issues || [],
    warnings: input.warnings || [],
    recommendations: input.recommendations || [],
    summary: input.summary,
    dimensions: input.dimensions,
    metrics: input.metrics,
    timestamp: input.timestamp
  }
}];
